using System.IO;
namespace PhotoTrail.Windows;
internal sealed record LocationValues(string Country,string State,string City,string Sublocation,string CountryCode,bool Iptc=false,bool Overwrite=false,bool Independent=false,string Origin="user-manual") {
 internal Dictionary<string,string> Fields(){if(!Independent||Origin!="user-manual")throw new ArgumentException("D06：仅已确认独立手填来源可采用；在线结果持久化未获许可。");string[] tags=Iptc?["IPTC:Country-PrimaryLocationName","IPTC:Province-State","IPTC:City","IPTC:Sub-location","IPTC:Country-PrimaryLocationCode"]:["XMP-photoshop:Country","XMP-photoshop:State","XMP-photoshop:City","XMP-iptcCore:Location","XMP-iptcCore:CountryCode"];var values=new[]{Country,State,City,Sublocation,CountryCode};if(values.Any(v=>v is null||v.Length>2000||v.Any(char.IsControl)))throw new ArgumentException("地区输入无效。");if(CountryCode.Length>0&&(CountryCode.Length!=3||CountryCode.Any(c=>c is <'A' or >'Z')))throw new ArgumentException("国家码必须手填精确的大写"+"三"+"字母；不猜测码表。");var result=tags.Zip(values).Where(p=>p.Second.Length>0).ToDictionary(p=>p.First,p=>p.Second);if(result.Count==0)throw new ArgumentException("至少手填一项地区；留空不会清除。");PhotoDocument.ValidateChanges(result);return result;}
}
internal sealed record LocationAdoptionRow(string Path,string Hash,string? SidecarHash,long Revision,MapPoint Gps,IReadOnlyDictionary<string,string> Fields);
internal sealed record LocationAdoptionPlan(LocationValues Values,LocationAdoptionRow[] Rows,ImportSource[] Sources,DateTimeOffset Created) {
 internal static MapPoint RequireGps(PhotoDocument doc){var p=doc.Position();bool xmp=doc.Value("XMP-exif:GPSLatitude").Length>0||doc.Value("XMP-exif:GPSLongitude").Length>0||doc.Draft.ContainsKey("XMP-exif:GPSLatitude")||doc.Draft.ContainsKey("XMP-exif:GPSLongitude");string datum=xmp?doc.Value("XMP-exif:GPSMapDatum"):doc.Embedded.TryGetProperty("GPS:GPSMapDatum",out var d)?PhotoDocument.Text(d):"";if(p is null||datum.Replace("-","").Replace(" ","").ToUpperInvariant()!="WGS84")throw new ArgumentException("每张照片须明确有效WGS84坐标；缺失/未知基准不据显示假设采用地区。");return p;}
 internal static async Task<LocationAdoptionPlan> CreateAsync(PhotoDocument[] docs,LocationValues values,CancellationToken token=default){var fields=values.Fields();if(docs.Length is <1 or >3000||docs.Select(d=>d.FilePath).Distinct(StringComparer.OrdinalIgnoreCase).Count()!=docs.Length)throw new ArgumentException("地区范围为空、重复或超过3000。");var rows=new List<LocationAdoptionRow>();var sources=new List<ImportSource>();foreach(var doc in docs){token.ThrowIfCancellationRequested();InplaceHistory.RequireClear(doc.SidecarPath is {} side?[doc.FilePath,side]:[doc.FilePath]);if(!doc.CanStage||fields.Keys.Any(tag=>!MetadataFields.CanEdit(doc,tag)))throw new ArgumentException("所选含只读或不支持精确地区字段的来源，未冻结。");var gps=RequireGps(doc);long revision=doc.DraftRevision;await doc.EnsureUnchangedAsync(token);sources.Add(ImportSource.Read(doc.FilePath));if(doc.SidecarPath is {} s)sources.Add(ImportSource.Read(s));var changes=fields.Where(p=>values.Overwrite||string.IsNullOrWhiteSpace(doc.Value(p.Key))).ToDictionary();var clone=doc.BatchSnapshot();clone.StageDraft(changes);if(doc.DraftRevision!=revision||doc.Position()!=gps)throw new IOException("冻结期间GPS/草稿改变。");rows.Add(new(doc.FilePath,doc.SourceHash,doc.SidecarHash,revision,gps,changes));}return new(values,rows.ToArray(),sources.ToArray(),DateTimeOffset.Now);}
 internal void Require(PhotoDocument[] docs){if(docs.Length!=Rows.Length)throw new IOException("地区目标集合已变化。");foreach(var source in Sources)source.RequireCurrent();foreach(var (doc,i) in docs.Select((d,i)=>(d,i))){var row=Rows[i];if(doc.FilePath!=row.Path||doc.SourceHash!=row.Hash||doc.SidecarHash!=row.SidecarHash||doc.DraftRevision!=row.Revision||RequireGps(doc)!=row.Gps||!doc.CanStage)throw new IOException("地区冻结来源、GPS或草稿已变化，未采用。");}}
}
